entities:
{
  name: 'page',
  columns: {
    id: {
      type: 'varchar',
      primary: true
    },
    title: {
      type: 'varchar',
      nullable: true
    },
    body: {
      type: 'text'
    }
  },
  relations: {
    tags: {
      type: 'one-to-many',
      target: 'pageTag',
      cascade: true,
      inverseSide: 'page'
    }
  }
}

{
  name: 'pageTag',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    name: {
      type: 'varchar'
    },
    start: {
      type: 'date',
      nullable: true
    },
    end: {
      type: 'date',
      nullable: true
    }
  },
  relations: {
    page: {
      type: 'many-to-one',
      target: 'page',
      onDelete: 'CASCADE',
      inverseSide: 'tags'
    }
  }
}

components.findOptions:
{
  where: {
    id: params.id,
    tags: {
      name: 'PUBLISHED',
      start: Raw(alias => `${alias} is null or ${alias} < :current`, {current: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :current`, {current: new Date()})
    }
  }
}

{
  select: {
    id: true,
    title: true
  },
  where: {
    tags: {
      name: 'MENU',
      start: Raw(alias => `${alias} is null or ${alias} < :current`, {current: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :current`, {current: new Date()})
    }
  }
}
